create or replace function public.monthly_report(month_start date, selected_unit_id uuid default null) returns table(unit_id uuid,body_number text,remittance_due_centavos bigint,remittance_paid_centavos bigint,outstanding_centavos bigint,total_expense_centavos bigint,net_income_centavos bigint) language sql stable security definer set search_path=public as $$ select * from public.dashboard_monthly_unit_summary(month_start) where selected_unit_id is null or unit_id=selected_unit_id $$;
